function validate([grid]) {
  const n = grid.length;
  if (n < 1 || n > 100) return 'grid needs 1 to 100 rows.';
  for (const row of grid) {
    if (row.length !== n) return 'grid must be square: every row needs n values.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 1e9)) return 'Each value is an integer from 0 to 10^9.';
  }
  return null;
}

