function maximumScore(grid) {
  const n = grid.length;
  const prefix = Array.from({ length: n }, () => new Array(n + 1).fill(0));
  for (let col = 0; col < n; col++) {
    for (let row = 0; row < n; row++) {
      prefix[col][row + 1] = prefix[col][row] + grid[row][col];
    }
  }
  let open = new Array(n + 1).fill(0);
  let counted = new Array(n + 1).fill(0);
  for (let col = 1; col < n; col++) {
    const nextOpen = new Array(n + 1).fill(0);
    const nextCounted = new Array(n + 1).fill(0);
    for (let prev = 0; prev <= n; prev++) {
      const best = Math.max(open[prev], counted[prev]);
      for (let height = 0; height <= n; height++) {
        if (height > prev) {
          const gain = prefix[col - 1][height] - prefix[col - 1][prev];
          nextOpen[height] = Math.max(nextOpen[height], open[prev] + gain, counted[prev]);
        } else {
          const gain = prefix[col][prev] - prefix[col][height];
          nextOpen[height] = Math.max(nextOpen[height], best);
          nextCounted[height] = Math.max(nextCounted[height], best + gain);
        }
      }
    }
    open = nextOpen;
    counted = nextCounted;
  }
  return Math.max(...open, ...counted);
}

