function maximumScore(grid) {
  const n = grid.length;
  const black = new Array(n).fill(0);
  let best = 0;
  const score = () => {
    let total = 0;
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++) {
        if (i < black[j]) continue;
        const leftBlack = j > 0 && i < black[j - 1];
        const rightBlack = j + 1 < n && i < black[j + 1];
        if (leftBlack || rightBlack) total += grid[i][j];
      }
    return total;
  };
  // Try every column height from 0 (all white) to n (all black).
  const choose = j => {
    if (j === n) { best = Math.max(best, score()); return; }
    for (let h = 0; h <= n; h++) { black[j] = h; choose(j + 1); }
  };
  choose(0);
  return best;
}

