function generate(rand, size) {
  const n = size === 'large' ? 96 + Math.floor(rand() * 5) : 1 + Math.floor(rand() * 5);
  const limit = size === 'large' || rand() < 0.3 ? 1e9 : 20;
  const zeros = rand() * 0.6;
  const grid = [];
  for (let row = 0; row < n; row++) {
    const line = [];
    for (let col = 0; col < n; col++) line.push(rand() < zeros ? 0 : Math.floor(rand() * (limit + 1)));
    grid.push(line);
  }
  return [grid];
}
